// Generates src/lib/api-schema.d.ts from the backend's OpenAPI document.
//
//   pnpm api:types                         from the running dev backend
//   pnpm api:types ../backend/openapi.json from a file (the backend commits one)
//   pnpm api:types:check [source]          fail if the committed types are stale
//
// The source can also be set with OPENAPI_SPEC. The generated file is
// committed, so building the app never needs the backend.
import { existsSync, readFileSync, writeFileSync } from 'node:fs'
import { resolve } from 'node:path'
import { pathToFileURL } from 'node:url'
import openapiTS, { astToString } from 'openapi-typescript'
import { format, resolveConfig } from 'prettier'

const OUTPUT = resolve(import.meta.dirname, '../src/lib/api-schema.d.ts')
const DEFAULT_SOURCE = 'http://localhost:8888/api-docs-json'

const args = process.argv.slice(2)
const check = args.includes('--check')
const source = args.find((arg) => !arg.startsWith('--')) ?? process.env.OPENAPI_SPEC ?? DEFAULT_SOURCE
const url = /^https?:\/\//.test(source) ? new URL(source) : pathToFileURL(resolve(source))

const HEADER = `// Generated by \`pnpm api:types\` from the backend's OpenAPI document. Do not edit.
// Property names are snake_case, as on the wire. Use the camelCased views in
// ./api-types.ts, which match what the axios client hands back.
`

let content
try {
    const generated = HEADER + '\n' + astToString(await openapiTS(url))
    // Formatted like the rest of src, so the pre-commit Prettier run leaves it
    // unchanged and --check compares like with like.
    content = await format(generated, { ...(await resolveConfig(OUTPUT)), filepath: OUTPUT })
} catch (error) {
    console.error(`Could not read the OpenAPI document from ${source}: ${error.message}`)
    if (source === DEFAULT_SOURCE) console.error('Start the backend, or pass the path to its openapi.json.')
    process.exit(1)
}

if (check) {
    const committed = existsSync(OUTPUT) ? readFileSync(OUTPUT, 'utf8').replace(/\r\n/g, '\n') : ''
    if (committed !== content) {
        console.error('src/lib/api-schema.d.ts is out of date with the API. Run `pnpm api:types` and commit it.')
        process.exit(1)
    }
    console.log('src/lib/api-schema.d.ts is up to date')
} else {
    writeFileSync(OUTPUT, content)
    console.log(`Wrote src/lib/api-schema.d.ts from ${source}`)
}
